const trigger = $('WhatsApp Trigger').first();
const configItem = $input.first().json;

const msg = (trigger.json.messages || [])[0] || {};
const msgType = msg.type || 'text';

const mm = configItem.multimedia_enabled || {};
const imagenEnabled = !!mm.imagen;
const audioEnabled  = !!mm.audio;

const esImagen = msgType === 'image';
const esAudio  = msgType === 'audio' || msgType === 'voice';

// Solo se enruta a procesamiento multimedia si la capacidad esta habilitada en config.
// Si esta deshabilitada, el mensaje sigue la ruta de texto (Pasar sin multimedia).
const tieneImagen = esImagen && imagenEnabled;
const tieneAudio  = esAudio && audioEnabled;

const botonReply = msg.interactive?.button_reply || msg.interactive?.list_reply || null;
let textoEntrada = botonReply?.title || msg.text?.body || msg.image?.caption || '';

// Gap: el cliente envia imagen/audio con la capacidad deshabilitada y sin texto.
// Se inyecta una instruccion para que el agente responda en vez de procesar un turno vacio.
const mediaDeshabilitada = (esImagen && !imagenEnabled) || (esAudio && !audioEnabled);
if (mediaDeshabilitada && !textoEntrada) {
  const tipo = esImagen ? 'una imagen' : 'un audio';
  textoEntrada = '[SISTEMA: el cliente envio ' + tipo + ' pero el procesamiento de imagenes y audio esta deshabilitado. Indicale amablemente que por ahora no tienes esa capacidad y ofrecele mostrarle el catalogo.]';
}

return [{
  json: {
    chatInput: textoEntrada,
    boton_id: botonReply?.id || '',
    sessionId: msg.from || '',
    tools_enabled: configItem.tools_enabled,
    multimedia_enabled: configItem.multimedia_enabled,
    can_escalate_to_human: configItem.can_escalate_to_human,
    can_request_additional: configItem.can_request_additional,
    recomendaciones: configItem.recomendaciones,
    welcome_message: configItem.welcome_message,
    business_info: configItem.business_info,
    faq: configItem.faq,
    contact: configItem.contact,
    tiene_imagen: tieneImagen,
    tiene_audio: tieneAudio,
    imagen_url: msg.image?.url || '',
    imagen_id: msg.image?.id || '',
    audio_url: msg.audio?.url || msg.voice?.url || '',
    audio_id: msg.audio?.id || msg.voice?.id || ''
  },
  binary: {}
}];

const multimedia = $('Detectar Multimedia').first().json;
const analisisImg = $input.first().json;
return [{ json: {
  ...multimedia,
  contexto_imagen: analisisImg.contexto_imagen || 'Sin imagen.',
  contexto_audio: 'Sin audio.'
} }];

const multimedia = $('Detectar Multimedia').first().json;
const transcripcion = $input.first().json;
return [{ json: {
  ...multimedia,
  chatInput: transcripcion.mensaje_inyectar || multimedia.chatInput,
  contexto_imagen: 'Sin imagen.',
  contexto_audio: transcripcion.contexto_audio || 'Sin audio.'
} }];

const data = $input.first().json;
return [{ json: {
  ...data,
  contexto_imagen: 'Sin imagen.',
  contexto_audio: 'Sin audio.'
} }];

const data = $input.first().json;
const chatInput = (data.chatInput || '').trim();

let identificador = '';

// 1) El mensaje es esencialmente solo el codigo o telefono (con o sin separadores, con o sin letras de prefijo)
const limpio = chatInput.replace(/[\s\-().]/g, '');
if (/^[A-Za-z]{0,5}\d{4,15}$/.test(limpio)) {
  identificador = limpio;
} else {
  // 2) Viene dentro de una frase: codigo con prefijo de letras, o numero largo (>=6 digitos)
  const sueltos = chatInput.replace(/[\s\-().]/g, ' ');
  const matchCodLetra = chatInput.match(/\b([A-Za-z]{1,5}\d{4,12})\b/);
  const matchNum = sueltos.match(/\b(\d{6,15})\b/);
  identificador = (matchCodLetra && matchCodLetra[1]) || (matchNum && matchNum[1]) || '';
}

return [{
  json: {
    ...data,
    identificador_detectado: identificador,
    need_lookup: identificador.length > 0
  }
}];

// ===== LISTA BLANCA DE CODIGOS DE CLIENTE =====================
// Agrega aqui los codigos permitidos, ej: ['3502561', '3502999'].
// Lista VACIA = sin restriccion (funciona como hoy, pasan todos).
const ALLOWED_CLIENT_CODES = ['1000884', '1001673', '1000355', '1001776', '1002990', '1001169', '1001433', '1002286', '1000242', '1010326', '1004698', '1009305', '1004702', '1009878', '10007730', '3784980', '3784981', '3784982', '3784983', '3784984', '3784985', '3784986', '3784987', '3784988', '3784989', '3784990', '3784991', '3784992', '3784993', '3784994', '3784995'];
const MENSAJE_BLOQUEO = 'Por el momento tu codigo de cliente no esta habilitado para hacer pedidos por este medio. Si tienes un codigo de cliente o telefono habilitado, compartemelo. 🙏';
// =============================================================

const detector = $('Detectar Identificador').first().json;
const lookupRows = $input.all().map(i => i.json).filter(r => r && r.cliente_id);

let perfil;

if (lookupRows.length > 0) {
  const row = lookupRows[0];
  const esRecurrente = (row.total_ordenes || 0) > 0;
  perfil = {
    estado: 'IDENTIFICADO_AHORA',
    cliente_id: row.cliente_id,
    empresa: row.empresa,
    tienda: '10000',
    nombre: String(row.nombre || '').trim().replace(/\s+/g, ' '),
    telefono: String(row.telefono || '').trim(),
    total_ordenes: row.total_ordenes || 0,
    es_recurrente: esRecurrente,
    es_nuevo: !esRecurrente,
    producto_mas_frecuente_nombre: row.producto_mas_frecuente_nombre || '',
    mensaje_lookup: ''
  };
} else if (detector.need_lookup) {
  perfil = {
    estado: 'LOOKUP_FALLIDO',
    cliente_id: '', empresa: '', tienda: '', nombre: '', telefono: '',
    total_ordenes: 0, es_recurrente: false, es_nuevo: false,
    producto_mas_frecuente_nombre: '',
    mensaje_lookup: `No encontré ningún cliente con el dato '${detector.identificador_detectado}'.`
  };
} else {
  perfil = {
    estado: 'SIN_LOOKUP',
    cliente_id: '', empresa: '', tienda: '', nombre: '', telefono: '',
    total_ordenes: 0, es_recurrente: false, es_nuevo: false,
    producto_mas_frecuente_nombre: '',
    mensaje_lookup: ''
  };
}

// El gateo del catalogo/carrito es DURO en el nodo Filtro (al emitir el link).
// Aqui ya NO se bloquea la conversacion: todos reciben soporte basico (FAQ, contacto, info).
const accesoBloqueado = false;

// habilitado para pedidos: lista vacia = todos; con lista = solo codigos en ella.
// Solo es fiable cuando hay cliente_id (estado IDENTIFICADO_AHORA); en SIN_LOOKUP el agente lo lee de la marca.
perfil.habilitado = ALLOWED_CLIENT_CODES.length === 0
  || (!!perfil.cliente_id && ALLOWED_CLIENT_CODES.map(String).includes(String(perfil.cliente_id)));

return [{
  json: {
    ...detector,
    perfil: perfil,
    acceso_bloqueado: accesoBloqueado,
    mensaje_bloqueo: MENSAJE_BLOQUEO,
    allowed_client_codes: ALLOWED_CLIENT_CODES.map(String)
  }
}];

let respuesta = $input.first().json.output || '';
let ordenConfirmada = false;
let esTplPlantilla  = false;
let esCartLink      = false;
let cartLinkUrl     = '';
let cartCodcliente  = '';
let cartEmpresa     = '';
let tplNombre = '';
let tplLang   = 'es_MX';
let tplVars   = [];

// Extrae [SEND_TEMPLATE:{...}] respetando llaves anidadas
const MARKER = '[SEND_TEMPLATE:';
const mStart = respuesta.indexOf(MARKER);
if (mStart !== -1) {
  const jsonStart = mStart + MARKER.length;
  let depth = 0, jsonEnd = -1;
  for (let i = jsonStart; i < respuesta.length; i++) {
    if      (respuesta[i] === '{') depth++;
    else if (respuesta[i] === '}') { depth--; if (depth === 0) { jsonEnd = i; break; } }
  }
  if (jsonEnd !== -1 && respuesta[jsonEnd + 1] === ']') {
    esTplPlantilla = true;
    try {
      const d = JSON.parse(respuesta.substring(jsonStart, jsonEnd + 1));
      tplNombre = d.name || '';
      tplLang   = d.lang || 'es_MX';
      tplVars   = Array.isArray(d.vars) ? d.vars : [];
    } catch {}
    respuesta = (respuesta.substring(0, mStart) + respuesta.substring(jsonEnd + 2)).trim();
  }
}

// Extrae [SEND_CART_LINK:{...}]
const CART_MARKER = '[SEND_CART_LINK:';
const cStart = respuesta.indexOf(CART_MARKER);
if (cStart !== -1) {
  const jsonStart = cStart + CART_MARKER.length;
  let depth = 0, jsonEnd = -1;
  for (let i = jsonStart; i < respuesta.length; i++) {
    if      (respuesta[i] === '{') depth++;
    else if (respuesta[i] === '}') { depth--; if (depth === 0) { jsonEnd = i; break; } }
  }
  if (jsonEnd !== -1 && respuesta[jsonEnd + 1] === ']') {
    esCartLink = true;
    try {
      const d = JSON.parse(respuesta.substring(jsonStart, jsonEnd + 1));
      cartLinkUrl = d.url || '';
      cartCodcliente = d.codcliente || '';
      cartEmpresa = d.empresa || '';
    } catch {}
    respuesta = (respuesta.substring(0, cStart) + respuesta.substring(jsonEnd + 2)).trim();
  }
}

// ===== GATE DURO: catalogo/carrito solo para codigos habilitados =====
// Soporte basico queda abierto a todos; aqui solo se gatea el link del carrito.
if (esCartLink) {
  const cp = $('Construir Perfil').first().json || {};
  const allowed = Array.isArray(cp.allowed_client_codes) ? cp.allowed_client_codes : [];
  if (allowed.length > 0 && !allowed.includes(String(cartCodcliente))) {
    esCartLink = false;
    cartLinkUrl = '';
    cartCodcliente = '';
    cartEmpresa = '';
    respuesta = cp.mensaje_bloqueo || 'Por el momento tu codigo no esta habilitado para hacer pedidos por este medio.';
  }
}

// Extrae [SEND_BUTTONS:{...}] respetando llaves anidadas
let esBotones   = false;
let botonesBody = '';
let botonesList = [];
const BTN_MARKER = '[SEND_BUTTONS:';
const bStart = respuesta.indexOf(BTN_MARKER);
if (bStart !== -1) {
  const jsonStart = bStart + BTN_MARKER.length;
  let depth = 0, jsonEnd = -1;
  for (let i = jsonStart; i < respuesta.length; i++) {
    if      (respuesta[i] === '{') depth++;
    else if (respuesta[i] === '}') { depth--; if (depth === 0) { jsonEnd = i; break; } }
  }
  if (jsonEnd !== -1 && respuesta[jsonEnd + 1] === ']') {
    esBotones = true;
    try {
      const d = JSON.parse(respuesta.substring(jsonStart, jsonEnd + 1));
      botonesBody = d.body || '';
      botonesList = Array.isArray(d.buttons) ? d.buttons : [];
    } catch {}
    respuesta = (respuesta.substring(0, bStart) + respuesta.substring(jsonEnd + 2)).trim();
  }
}

// Extrae [SEND_IMAGE] (usa imagen de bienvenida fija) o [SEND_IMAGE:{"url":"..."}]
let esImagen  = false;
let imagenUrl = '';
const IMG_MARKER = '[SEND_IMAGE';
const iStart = respuesta.indexOf(IMG_MARKER);
if (iStart !== -1) {
  const afterMarker = iStart + IMG_MARKER.length;
  if (respuesta[afterMarker] === ']') {
    esImagen = true;
    respuesta = (respuesta.substring(0, iStart) + respuesta.substring(afterMarker + 1)).trim();
  } else if (respuesta[afterMarker] === ':') {
    const jsonStart = afterMarker + 1;
    let depth = 0, jsonEnd = -1;
    for (let k = jsonStart; k < respuesta.length; k++) {
      if      (respuesta[k] === '{') depth++;
      else if (respuesta[k] === '}') { depth--; if (depth === 0) { jsonEnd = k; break; } }
    }
    if (jsonEnd !== -1 && respuesta[jsonEnd + 1] === ']') {
      esImagen = true;
      try {
        const d = JSON.parse(respuesta.substring(jsonStart, jsonEnd + 1));
        imagenUrl = d.url || '';
      } catch {}
      respuesta = (respuesta.substring(0, iStart) + respuesta.substring(jsonEnd + 2)).trim();
    }
  }
}

// Extrae [ORDER_ACTION:{...}] (confirmar/modificar/cancelar pedido por texto)
let esOrderAction = false;
let orderBotonId  = '';
const OA_MARKER = '[ORDER_ACTION:';
const oaStart = respuesta.indexOf(OA_MARKER);
if (oaStart !== -1) {
  const jsonStart = oaStart + OA_MARKER.length;
  let depth = 0, jsonEnd = -1;
  for (let i = jsonStart; i < respuesta.length; i++) {
    if      (respuesta[i] === '{') depth++;
    else if (respuesta[i] === '}') { depth--; if (depth === 0) { jsonEnd = i; break; } }
  }
  if (jsonEnd !== -1 && respuesta[jsonEnd + 1] === ']') {
    try {
      const oa = JSON.parse(respuesta.substring(jsonStart, jsonEnd + 1));
      const act = (oa.action || '').toUpperCase();
      const map = { CONFIRM: 'ORDER_CONFIRM', MODIFY: 'ORDER_MODIFY', CANCEL: 'ORDER_CANCEL' };
      if (map[act]) { esOrderAction = true; orderBotonId = map[act]; }
    } catch {}
    respuesta = (respuesta.substring(0, oaStart) + respuesta.substring(jsonEnd + 2)).trim();
  }
}

if (respuesta.includes('[ORDEN_CONFIRMADA]')) {
  ordenConfirmada = true;
  respuesta = respuesta.replace('[ORDEN_CONFIRMADA]', '').trim();
}

respuesta = respuesta.replace(/<!--SESSION:[^>]*-->/g, '').trim();

function limpiarTexto(s) {
  if (!s) return s;
  return s
    .replace(/\*\*+/g, '*')
    .split('\n').map(l => l.replace(/[ \t]{2,}/g, ' ').replace(/[ \t]+$/, '')).join('\n')
    .trim();
}
respuesta = limpiarTexto(respuesta);
botonesBody = limpiarTexto(botonesBody);

const sessionId = $('WhatsApp Trigger').first().json.messages[0].from;

return [{ json: {
  output:          respuesta,
  orden_confirmada: ordenConfirmada,
  es_plantilla:    esTplPlantilla,
  es_cart_link:    esCartLink,
  cart_link_url:   cartLinkUrl,
  cart_codcliente: cartCodcliente,
  cart_empresa:    cartEmpresa,
  es_botones:      esBotones,
  botones_body:    botonesBody,
  botones_list:    botonesList,
  es_imagen:       esImagen,
  imagen_send_url: imagenUrl,
  template_nombre: tplNombre,
  template_lang:   tplLang,
  template_vars:   tplVars,
  es_order_action: esOrderAction,
  order_boton_id:  orderBotonId,
  sessionId:       sessionId
} }];

// Procesa la respuesta del endpoint y arma flags para el resto del flujo.
const resp = $input.first().json;
const config = Array.isArray(resp) ? resp[0]?.data : resp?.data;

if (!config) {
  throw new Error('Respuesta de configuración inválida');
}

const caps = config.agentCapabilities || {};
const kb = config.knowledgeBase || {};
const convStart = config.conversationStart || {};
const recom = config.recommendations || {};

const result = {
  // Banderas para tools del agente
  tools_enabled: {
    listar_categorias:       !!caps.checkAvailability,
    buscar_productos:        !!caps.checkAvailability,
    obtener_recomendaciones: !!caps.suggestProducts,
    ver_historial_compras:   false,
    generar_link_carrito:    !!caps.startOrder,
    obtener_plantillas:      true
  },

  // Banderas para procesamiento multimedia
  multimedia_enabled: {
    imagen: !!caps.imageAnalysis,
    audio:  !!caps.voiceRecognition
  },

  // Otras capabilities
  can_escalate_to_human:  !!caps.escalateToHuman,
  can_request_additional: !!caps.requestAdditionalData,

  // Configuración de recomendaciones (cómo presentarlas)
  recomendaciones: {
    enabled:                  !!recom.enabled,
    max_recommendations:      recom.maxRecommendations || 5,
    max_recommended_products: recom.maxRecommendedProducts || 4,
    format:                   recom.format || 'CAROUSEL'
  },

  // Bienvenida configurable
  welcome_message: convStart.welcomeMessage || '¡Hola! ¿En qué puedo ayudarte?',

  // Knowledge base
  business_info: kb.businessGeneralInfo || [],
  faq:           kb.faq || [],
  contact:       kb.contact || {}
};

// ===== MODO LINEAL TEMPORAL — overrides ===========================
// Solo flujo de carrito -> confirmacion. Deshabilitado de momento (no removido):
// busqueda de productos, categorias, recomendaciones, historial, plantillas,
// escalacion a humano, analisis de imagen y audio.
// El link de carrito queda forzado a activo: es el flujo principal.
// Para revertir y volver a respetar la config del backend: borrar este bloque.
result.tools_enabled.listar_categorias      = false;
result.tools_enabled.buscar_productos       = false;
result.tools_enabled.obtener_recomendaciones = false;
result.tools_enabled.ver_historial_compras  = false;
result.tools_enabled.obtener_plantillas     = false;
result.tools_enabled.generar_link_carrito   = true;
result.can_escalate_to_human                = false;
result.multimedia_enabled.imagen            = false;
result.multimedia_enabled.audio             = false;
// ==================================================================

return [{ json: result }];

const data = $input.first().json;
const phone = data.sessionId;
const globalData = $getWorkflowStaticData('global');
const version = globalData['conv_' + phone] || '0';
globalData['__current_phone__'] = phone;
return [{ json: { ...data, session_version: version } }];

const globalData = $getWorkflowStaticData('global');
const phone = globalData['__current_phone__'] || '';
if (phone) {
  const key = 'conv_' + phone;
  const current = parseInt(globalData[key] || '0');
  globalData[key] = String(current + 1);
}
return 'Conversación finalizada correctamente. La próxima vez que el usuario escriba iniciará una sesión completamente nueva desde cero.';

const data = $input.first().json;
const vars = Array.isArray(data.template_vars) ? data.template_vars : [];

const components = vars.length > 0
  ? [{ type: 'body', parameters: vars.map(v => ({ type: 'text', text: String(v) })) }]
  : [];

return [{ json: {
  ...data,
  template_components: components
} }];

